/**
 * Stone sprites.
 *
 * The images are generated by `scripts/make-assets.mjs` into src/web/assets
 * and copied to frontend/dist/assets by sync-dist. They are loaded by
 * relative URL (the page CSP is `img-src 'self' data:`), lazily, once.
 *
 *   const m = await loadMaterials();
 *   const img = m.white[stoneVariant(x, y, WHITE)];           // stone sprite
 *   ctx.drawImage(img, cx - r, cy - r, 2 * r, 2 * r);        // disc fills the sprite
 *
 * The board itself is one plain colour (board.js THEME). Stone sprites are
 * 256×256 with straight alpha; the
 * disc's diameter equals the sprite width; lighting is from the top-left; no
 * shadow is baked in, so draw a contact shadow first. For crisp downscaling
 * set `ctx.imageSmoothingQuality = "high"`.
 *
 * Nothing here throws: a failed image resolves as null (or is left out of
 * the variant arrays), and callers keep their procedural fallback.
 */

const STONE_COUNTS = { black: 4, white: 8 };

let base = "assets/";

function assetURL(rel) {
  return base + rel;
}

function loadImage(rel) {
  return new Promise((resolve) => {
    try {
      if (typeof Image === "undefined") return resolve(null);
      const img = new Image();
      img.decoding = "async";
      img.onload = () => {
        if (typeof img.decode === "function") img.decode().then(() => resolve(img), () => resolve(img));
        else resolve(img);
      };
      img.onerror = () => resolve(null);
      img.src = assetURL(rel);
    } catch (_) {
      resolve(null);
    }
  });
}

let cache = null;

/**
 * Load every stone sprite once. Resolves to `{ black: [...], white: [...] }`;
 * missing images are omitted.
 */
export function loadMaterials() {
  if (cache) return cache;
  const black = Promise.all(Array.from({ length: STONE_COUNTS.black }, (_, i) => loadImage(`stones/black-${i}.png`)));
  const white = Promise.all(Array.from({ length: STONE_COUNTS.white }, (_, i) => loadImage(`stones/white-${i}.png`)));
  cache = Promise.all([black, white])
    .then(([b, w]) => ({ black: b.filter(Boolean), white: w.filter(Boolean) }))
    .catch(() => ({ black: [], white: [] }));
  return cache;
}

function hash(x, y, salt) {
  let h = (x * 374761393 + y * 668265263 + salt * 2246822519) ^ 0x27d4eb2f;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = Math.imul(h ^ (h >>> 16), 2246822519);
  return (h ^ (h >>> 15)) >>> 0;
}

/**
 * A stable variant index for the stone at (x, y): the same point and colour
 * always give the same look. `color` may be 1 / -1 (rules.js BLACK / WHITE)
 * or "black" / "white". Pass `count` if fewer sprites loaded than expected.
 */
export function stoneVariant(x, y, color, count) {
  const white = color === -1 || color === "white" || color === "w" || color === "W";
  const n = Math.max(1, count || (white ? STONE_COUNTS.white : STONE_COUNTS.black));
  return hash(x | 0, y | 0, white ? 2 : 1) % n;
}
